ai_sql:
SELECT (COUNT(*) FILTER (WHERE nutriscore_grade = 'a') * 100.0) / COUNT(*) AS share_a_percent
FROM products
WHERE nutriscore_grade IS NOT NULL;

SELECT 100.0 * SUM(CASE WHEN nova_group = 4 THEN 1 ELSE 0 END) / COUNT(*) AS share_percent
FROM products
WHERE is_organic = true AND nova_group IS NOT NULL;
